function u(n,t){return n[0]*t[0]+n[1]*t[1]+n[2]*t[2]}function a(n){return n.length===3&&n.every(Number.isFinite)}function M(n,t){if(!a(n)||!a(t.forward)||!a(t.right)||!a(t.up))return null;const r=Math.hypot(n[0],n[1],n[2]);if(!Number.isFinite(r)||r<=.05)return null;const o=[n[0]/r,n[1]/r,n[2]/r],e=u(o,t.right),i=Math.min(1,Math.max(-1,u(o,t.up))),c=u(o,t.forward);return{u:((Math.atan2(e,c)/(2*Math.PI)+.5)%1+1)%1,v:Math.min(1,Math.max(0,.5-Math.asin(i)/Math.PI)),depth:r}}function p(n,t,r=9.88){if(![n,t,r].every(Number.isFinite)||r<=0)return null;const o=h(n,t);if(!o)return null;const[e,i,c]=o;return[-r*c,r*i,-r*e]}function h(n,t){if(![n,t].every(Number.isFinite))return null;const r=(n%1+1)%1,o=Math.min(1,Math.max(0,t)),e=(r-.5)*Math.PI*2,i=(.5-o)*Math.PI,c=Math.cos(i);return[c*Math.sin(e),Math.sin(i),c*Math.cos(e)]}export{M as a,p};
